with f as materialized (select app_private.void_sale((select id from public.accounting_sessions where reservation_id = 'ac3d008f-e09e-4d7e-8656-dc5661c8829e' and status = 'completed'), '同時試験', 'staff', '同時試験')->>'status' as r, clock_timestamp() as t) select f.r || ' ｜処理 ' || to_char(f.t at time zone 'Asia/Tokyo', 'HH24:MI:SS.MS') || ' 鍵を離す ' || to_char(clock_timestamp() at time zone 'Asia/Tokyo', 'HH24:MI:SS.MS') as r from f cross join lateral (select pg_sleep(20) where f.r is not null) s;
